import { ADMIN_RECEIPTS_ROUTE } from "../src/features/runners/contract";
import { redactError } from "./redact";
import { shapeRows } from "./shape";
import { writeHeaders } from "./target";
// A repository's stack route as the app's outbox calls it (docs/features/todos.md): specs that set lanes, commit
// TODOs to wait on, or drop what they committed use it directly. Each write names the person it expects.
/** The stack route's answer to `body`. */
export const stackChange = async (page, repository, body) => {
    const response = await page.request.post(`/api/repos/${repository}/stack`, {
        data: { opId: crypto.randomUUID(), ...body },
        headers: writeHeaders(),
    });
    return {
        status: response.status(),
        body: (await response.json().catch(() => ({}))),
    };
};
/** Sets the stack's lanes and base, an Admin's change (decision 0135). */
export const configureStack = (page, repository, lanes, base) => stackChange(page, repository, { op: "configure", lanes, maxOpen: 200, base });
/** Drops TODO `number`, as a spec's cleanup: a TODO left open holds a stacked repository's later ones. */
export const dropTodo = (page, repository, number) => stackChange(page, repository, { op: "drop", number });
/** The TODO's state as the stack holds it (`GET /api/repos/<owner>/<name>/stack/<number>`), not as a device shows it. */
export const serverState = async (page, repository, number) => {
    const response = await page.request.get(`/api/repos/${repository}/stack/${number}`);
    return response.ok() ? (await response.json()).state : `HTTP ${response.status()}`;
};
/** The TODOs of `repository` still open, `only` those whose title has it: the stack's own answer, not a test's memory. */
const openTodos = async (page, repository, only) => (await shapeRows(page.request, `/api/shapes/todos?repo=${repository}&log=full`))
    .filter((todo) => todo.state !== "dropped" && todo.state !== "merged" && (only === undefined || todo.title.includes(only)));
/**
 * Drops every open TODO with `word` in its title. A commit whose answer was lost leaves a TODO no test has a number
 * for, and a Working one holds a lane from every test after it.
 */
export const dropWord = async (page, repository, word) => {
    for (const todo of await openTodos(page, repository, word))
        await dropTodo(page, repository, Number(todo.number));
};
/** How long a sweep waits for a retirement's receipt. */
const RETIRES_WITHIN_MS = 60_000;
/**
 * Puts a scratch repository back as a run needs it, through the product's own routes, and says what it found: no e2e
 * runner, no coding agent of one, no open TODO, one stacked lane. `pnpm e2e:prod` holds the test account's lock, so
 * nothing here is another run's: a run that was killed never reached its own cleanup, and its leavings would otherwise
 * hold the lane from every later test as a 60 s `queued` timeout.
 */
export const cleanScratch = async (page, repository) => {
    // Not every caller's test installs redaction (fleet.spec.ts): a request error here would carry the session cookie.
    try {
        return await reset(page, repository);
    }
    catch (error) {
        throw redactError(error);
    }
};
const reset = async (page, repository) => {
    const machines = await shapeRows(page.request, `/api/shapes/machines?repo=${repository}&log=full`);
    const leftRunners = machines
        .filter((machine) => machine.removed_at === null && machine.name.startsWith("e2e-"))
        .map((machine) => machine.name);
    // A retired runner keeps its row, so the deploy smoke's agents stay findable when a write of theirs that never answered
    // lands after both were retired (e2e/runner-registration.spec.ts). Reads, one per past smoke run; a write only for what's there.
    const strandedAgents = [];
    for (const machine of machines) {
        if (machine.removed_at === null || !machine.name.startsWith("e2e-smoke-"))
            continue;
        const agent = await page.request.get(`/api/repos/${repository}/agents/${machine.name}`);
        if (agent.status() === 200)
            strandedAgents.push(machine.name);
        else if (agent.status() !== 404)
            throw new Error(`GET agents/${machine.name} answered ${agent.status()}`);
    }
    // A 202 only starts a retirement: its receipt says how it ended.
    const remove = async (path) => {
        const response = await page.request.delete(`/api/repos/${repository}/${path}`, { headers: writeHeaders() });
        if (response.status() !== 202)
            throw new Error(`DELETE ${path} answered ${response.status()}`);
        const { execution } = (await response.json());
        const deadline = Date.now() + RETIRES_WITHIN_MS;
        for (;;) {
            const receipt = await page.request.get(`${ADMIN_RECEIPTS_ROUTE}${encodeURIComponent(execution)}`);
            if (receipt.status() === 200) {
                const { outcome } = (await receipt.json());
                if (outcome === "removed" || outcome === "missing")
                    return;
                throw new Error(`DELETE ${path} ended ${outcome}`);
            }
            if (Date.now() > deadline)
                throw new Error(`DELETE ${path} has no receipt after ${RETIRES_WITHIN_MS / 1000} s`);
            await new Promise((resolve) => setTimeout(resolve, 500));
        }
    };
    // The agent first, so nothing new is handed to the runner going away, and its runner stays to find it by if it can't go.
    for (const name of strandedAgents)
        await remove(`agents/${name}`);
    for (const name of leftRunners)
        await remove(`agents/${name}`);
    for (const name of leftRunners)
        await remove(`runners/${name}`);
    const leftTodos = await openTodos(page, repository);
    for (const todo of leftTodos) {
        const dropped = await dropTodo(page, repository, Number(todo.number));
        if (dropped.status !== 202)
            throw new Error(`dropping T${todo.number} answered ${dropped.status} ${dropped.body.code ?? ""}`);
    }
    const configured = await configureStack(page, repository, 1, "stacked");
    if (configured.status !== 202)
        throw new Error(`configuring the stack answered ${configured.status} ${configured.body.code ?? ""}`);
    return {
        runners: leftRunners,
        agents: strandedAgents,
        todos: leftTodos.map((todo) => `T${todo.number} ${todo.state}: ${todo.title}`),
    };
};
